import{_ as a,o as p,c as o,a5 as e}from"./chunks/framework.Cooo9kuv.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"470-批量复制pdf中的文本内容","日期":"2026-04-12T00:00:00.000Z","修改日期":"2026-04-12T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["PDF批处理"],"标签":["复制pdf文本","批量复制pdf文本到txt","提取pdf文本","提取pdf页面文本"]},"headers":[],"relativePath":"md/PDF批处理/470-批量复制pdf中的文本内容.md","filePath":"md/PDF批处理/470-批量复制pdf中的文本内容.md"}'),n={name:"md/PDF批处理/470-批量复制pdf中的文本内容.md"};function r(d,t,s,f,l,_){return p(),o("div",null,[...t[0]||(t[0]=[e('<h3 id="程序介绍" tabindex="-1">程序介绍 <a class="header-anchor" href="#程序介绍" aria-label="Permalink to &quot;程序介绍&quot;">​</a></h3><p>批量复制指定文件夹A下每个pdf中的文本到txt文档中，复制时每个pdf页面间使用 ≦ 1 ≧   ≦ 2 ≧  这样的序列分割标注页面，使得每个pdf文件复制文本内容后在txt文档中能够清晰明了。</p><p>支持子文件夹穿透，程序会自动创建以pdf文件名命名的txt文档，将pdf文本复制后写入txt文档中，txt文档最后会保存在pdf所在文件夹下，与pdf文档放在一起。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250422101548174528814870164.png" alt=""></p><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><p><strong>使用过程中可能会出现如下情况</strong></p><p>1、pdf页面为纯图片页面，这种情况是无法复制文本的，需要先将页面中的图片进行OCR识别处理</p><p>2、pdf页面为文本页面，但是复制后的文本出现一个字一个字的情况**(这种情况比较少见)**，这种情况也需要先使用OCR进行预处理添加搜索层，再次复制就不会出现一个字一个字的情况了，还要一种办法就是将pdf另存为pdfA可归档的格式</p><h3 id="操作方法" tabindex="-1">操作方法 <a class="header-anchor" href="#操作方法" aria-label="Permalink to &quot;操作方法&quot;">​</a></h3><p>1、如果需要复制pdf文档中的文本（pdf文档中的文本为文本类型时，非图片类型）适用<strong>程序2</strong>进行复制</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250422102741174528886169443.png" alt=""></p><p>2、如果无法正确复制文本，可使用<strong>程序1</strong>对pdf文件进行OCR处理</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250422102456174528869697111.png" alt=""></p><h3 id="适用系统环境" tabindex="-1">适用系统环境 <a class="header-anchor" href="#适用系统环境" aria-label="Permalink to &quot;适用系统环境&quot;">​</a></h3><p>win7及以上64位操作系统</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1714.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1714.html</a></p>',17)])])}const i=a(n,[["render",r]]);export{h as __pageData,i as default};
